float MIS = 0.01;

vec3 shade(in vec3 ro, in vec3 rd, inout uint rngState) {
    vec3 col = vec3(0.0);
    vec3 through = vec3(1.0);
    vec3 sunrd = normalize(vec3(0.15, 0.5, 1.0));
    vec3 sunrds = coneDir(sunrd, rngState, radians(sundeg));

    vec3 norm;
    float rough;
    bool doSpec;

    vec3 suncol = vec3(plancks(680.0, 5800.0), plancks(550.0, 5800.0), plancks(440.0, 5800.0)) * lighttrans(vec3(0.0, planetrad, 0.0), sunrd);

    for (int i = 0; i < bounces; i++) {
        hitinfo hit;
        hitinfo lighthit;
        hit.dist = far;
        lighthit.dist = far;

        scene(ro, rd, hit);

        if (hit.dist == far) {
            vec3 skys = vec3(0.0);
            if (rough <= MIS && doSpec) {
                skys = sky2(rd, sunrd, vec3(0.0));
            } else {
                skys = sky2(rd, sunrd, vec3(0.0));
            }
            col += max(skys, 0.0) * through;
            break;
        }

        rough = hit.rough;

        vec3 prd = rd;
        ro = (ro + rd * hit.dist) + hit.norm * 0.001;

        vec3 lightpos = vec3(5.0, 2.0, 4.0);
        lightpos += randV(rngState) * 1.0;
        vec3 lightrd = normalize(lightpos - ro);
        vec3 epic = max(brdf(hit.alb, hit.rough, hit.metal, hit.F0, hit.norm, -prd, lightrd), 0.0) * 2.0 * pi;
        float lightdist = distance(ro, lightpos);

        scene(ro, lightrd, lighthit);

        vec3 brdfs = vec3(0.0);
        rd = sampleSpecular(hit.alb, hit.rough, hit.metal, hit.F0, hit.norm, -prd, rngState, brdfs, doSpec);

        //if (lighthit.dist >= lightdist) col += vec3(1.0, 0.4, 0.05) * 40.0 * through * epic / pow(lightdist, 2.0);

        col += hit.emissive * through;

        through *= brdfs;

        {
        	float p = max(through.r, max(through.g, through.b));
        	if (randF(rngState) > p)
            	break;

        	// Add the energy we 'lose' by randomly terminating paths
        	through *= 1.0 / p;            
        }
    }

    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec4 m = iMouse;
    m.x = m.x/iResolution.x;
    m.y = m.y*2.0/iResolution.y;
    m = m * 2.0 - 1.0;
    m.x *= iResolution.x/iResolution.y;

    uint rngState = uint(uint(fragCoord.x) * uint(1973) + uint(fragCoord.y) * uint(9277) + uint(iFrame) * uint(26699)) | uint(1);
    vec2 uv = fragCoord/iResolution.xy * 2.0 - 1.0;
    vec2 uv2 = (fragCoord + rand2F(rngState)) / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x/iResolution.y;
    uv2.x *= iResolution.x / iResolution.y;

    float distance = 1.0 / tan(90.0 * 0.5 * pi / 180.0);

    vec3 ro = vec3(0.0, 0.0, 4.0);
    vec3 rd = normalize(vec3(uv2, -distance));

    //ro = vec3(uv.x, uv.y + 1.0, 3.0);
    //rd = vec3(0.0, 0.0, -1.0);


    vec3 col = texture( iChannel0, fragCoord/iResolution.xy ).xyz;
    float temp = texture( iChannel0, fragCoord/iResolution.xy ).w;

    if (iFrame == 0 || m.z > 0.0 || any(isnan(col))) {
        col = vec3(0.0);
        temp = 0.0;
    }

    if (iMouse.x > 0.0) {
        ro *= rotateX(m.y-1.5);
        ro *= rotateY(m.x);
        rd *= rotateX(m.y-1.5);
        rd *= rotateY(m.x);
    }

    vec3 newcol = vec3(0.0);
    for (int i = 0; i < renders; i++) {
        newcol += max(shade(ro, rd, rngState), 0.0);
    }
    newcol /= float(renders);

    col += newcol;
    temp += 1.0;

    fragColor = vec4(col,temp);
}

const float pi = 3.14159265358979323;
